'use strict';

// Helpers
function sc(diff, text, options, correctOptionId, info) { return { type: 'SingleChoice', difficulty: diff, text, imageUrl: null, options, correctOptionId, info }; }
function mc(diff, text, options, correctOptionIds, info) { return { type: 'MultipleChoice', difficulty: diff, text, imageUrl: null, options, correctOptionIds, info }; }
function ord(diff, text, items, info) { return { type: 'Ordering', difficulty: diff, text, imageUrl: null, items, info }; }
function fb(diff, text, blanks, candidates, info) { return { type: 'FillBlank', difficulty: diff, text, imageUrl: null, blanks, candidates, info }; }
const op4 = (a,b,c,d) => [{id:'a',text:a},{id:'b',text:b},{id:'c',text:c},{id:'d',text:d}];
const op5 = (a,b,c,d,e) => [{id:'a',text:a},{id:'b',text:b},{id:'c',text:c},{id:'d',text:d},{id:'e',text:e}];
const op6 = (a,b,c,d,e,f) => [{id:'a',text:a},{id:'b',text:b},{id:'c',text:c},{id:'d',text:d},{id:'e',text:e},{id:'f',text:f}];
const it4 = (a,b,c,d) => [{id:'i1',text:a},{id:'i2',text:b},{id:'i3',text:c},{id:'i4',text:d}];
const bl1 = (cid1) => [{id:'b1', correctCandidateId:cid1}];
const bl2 = (cid1, cid2) => [{id:'b1', correctCandidateId:cid1},{id:'b2', correctCandidateId:cid2}];
const cd5 = (a,b,c,d,e) => [{id:'c1',text:a},{id:'c2',text:b},{id:'c3',text:c},{id:'c4',text:d},{id:'c5',text:e}];

function q(id, payload) { return { id, text: payload.text, payload }; }

